// =============================================================================
// test_MLP_torch.cpp
// Unit tests for the Torch code paths of mc::MLP: reading a TorchScript module
// with mc::MLP::read_data, and its evaluation through Torch with
// mc::MLP::Options::EVALTORCH -- values (eval), Jacobian (grad), directional
// derivative (tang) and adjoint (adj) -- against the evaluation by MC++ of the
// weights read from the module.
//
// The models torch_*.pt are generated by test_MLP_torch.py; peak_*.pt are the
// models of test_Torch.cpp. The program must be run from their directory.
//
// Build (assuming MC++ and Torch headers are on the include path):
//   g++ -std=c++17 -O2 -DMC__USE_TORCH -I<path-to-mc++> -o test_MLP_torch test_MLP_torch.cpp <Torch libraries>
// Without MC__USE_TORCH the tests are skipped.
//
// Each test prints PASS or FAIL and a summary is printed at the end.
// The process exits with code 0 if every test passes, 1 otherwise.
// =============================================================================

#include <cmath>
#include <cstdio>
#include <functional>
#include <iostream>
#include <sstream>
#include <stdexcept>
#include <string>
#include <thread>
#include <vector>

#include "interval.hpp"
typedef mc::Interval I;

#include "ffmlp.hpp"

typedef mc::McCormick<I> MC;
using mc::FFGraph;
using mc::FFVar;

// -----------------------------------------------------------------------------
// Lightweight test harness
// -----------------------------------------------------------------------------
namespace test
{

static int total = 0, passed = 0, failed = 0;

struct Result
{
  bool ok;
  std::string msg;
};

inline bool
near(double a, double b, double tol = 1e-12)
{
  return std::fabs(a - b) <= tol * (1. + std::fabs(b));
}

inline bool
near(std::vector<double> const& a, std::vector<double> const& b, double tol = 1e-12)
{
  if (a.size() != b.size()) return false;
  for (size_t i = 0; i < a.size(); ++i)
    if (!near(a[i], b[i], tol)) return false;
  return true;
}

inline void
run(std::string const& name, std::function<Result()> fn)
{
  ++total;
  Result r;
  try
  {
    r = fn();
  }
  catch (std::exception const& e)
  {
    r = {false, std::string("exception: ") + e.what()};
  }
  catch (mc::FFBase::Exceptions& e)
  {
    r = {false, std::string("FFBase exception: ") + e.what()};
  }
  catch (...)
  {
    r = {false, "unknown exception"};
  }
  if (r.ok)
  {
    ++passed;
    std::printf("  PASS  %s\n", name.c_str());
  }
  else
  {
    ++failed;
    std::printf("  FAIL  %s -- %s\n", name.c_str(), r.msg.c_str());
  }
}

}  // namespace test


#ifdef MC__USE_TORCH

// Points of evaluation, for n inputs
static std::vector<std::vector<double>>
points(size_t const n)
{
  std::vector<std::vector<double>> p(3, std::vector<double>(n));
  for (size_t k = 0; k < 3; ++k)
    for (size_t i = 0; i < n; ++i) p[k][i] = 1.3 * std::cos(1. + 2.3 * k + 1.7 * i);
  return p;
}

// Values, Jacobian, directional derivative and adjoint at x: {y, J, J d, J^T w}
static std::vector<std::vector<double>>
derivatives(mc::MLP<I>& ANN, std::vector<double> const& x, bool const torch)
{
  size_t const nin = ANN.nin(), nout = ANN.nout();
  std::vector<double> y(nout), y1(nout), y2(nout), y3(nout), J(nout * nin), d(nin), w(nout), t(nout), a(nin);
  for (size_t i = 0; i < nin; ++i) d[i] = 0.5 - 0.3 * i;
  for (size_t k = 0; k < nout; ++k) w[k] = 1. + 0.7 * k;
  ANN.options.EVALTORCH = torch;
  ANN.eval(x.data(), y.data());
  ANN.grad(x.data(), J.data(), y1.data());
  ANN.tang(x.data(), d.data(), t.data(), y2.data());
  ANN.adj(x.data(), w.data(), a.data(), y3.data());
  ANN.options.EVALTORCH = false;
  // the values returned alongside the derivatives
  y.insert(y.end(), y1.begin(), y1.end());
  y.insert(y.end(), y2.begin(), y2.end());
  y.insert(y.end(), y3.begin(), y3.end());
  return {y, J, t, a};
}

static char const* const what[] = {"values", "Jacobian", "directional derivative", "adjoint"};

#endif

int
main()
{
#ifndef MC__USE_TORCH
  std::printf("test_MLP_torch: skipped, built without MC__USE_TORCH\n");
  return 0;
#else
  using test::near;
  using test::Result;
  using test::run;

  std::printf("Torch code paths of multilayer perceptrons\n");

  run("modules that are read: values and derivatives through Torch against MC++", []() -> Result {
    // {file, tolerance}: single precision, except one module
    std::vector<std::pair<std::string, double>> const models = {
        {"peak_Tanh_40L4.pt", 1e-5}, {"peak_ReLU_40L4.pt", 1e-5}, {"peak_Tanh_20L2.pt", 1e-5}, {"peak_ReLU_20L2.pt", 1e-5},
        {"torch_tanh.pt", 1e-5},     {"torch_tanh_double.pt", 1e-12}};
    for (auto const& [file, tol] : models)
    {
      mc::MLP<I> ANN;
      if (!ANN.read_data(file)) return {false, file + " not read"};
      for (auto const& x : points(ANN.nin()))
      {
        auto const ref = derivatives(ANN, x, false), der = derivatives(ANN, x, true);
        for (size_t k = 0; k < 4; ++k)
          if (!near(der[k], ref[k], tol)) return {false, file + ": " + what[k]};
      }
    }
    return {true, ""};
  });

  run("layers without activation or bias, output activation, dropout, module without batches", []() -> Result {
    // {file, inputs, outputs}
    std::vector<std::tuple<std::string, size_t, size_t>> const models = {
        {"torch_two_linear.pt", 2, 2}, {"torch_out_activ.pt", 2, 3}, {"torch_nobias.pt", 3, 2},
        {"torch_dropout.pt", 2, 2},    {"torch_nobatch.pt", 3, 2}};
    for (auto const& [file, nin, nout] : models)
    {
      mc::MLP<I> ANN;
      if (!ANN.read_data(file)) return {false, file + " not read"};
      if (ANN.nin() != nin || ANN.nout() != nout) return {false, file + ": sizes"};
      for (auto const& x : points(ANN.nin()))
      {
        auto const ref = derivatives(ANN, x, false), der = derivatives(ANN, x, true);
        for (size_t k = 0; k < 4; ++k)
          if (!near(der[k], ref[k], 1e-5)) return {false, file + ": " + what[k]};
        // dropout has no effect in evaluation: the same values again
        if (derivatives(ANN, x, true) != der) return {false, file + ": not repeatable"};
      }
    }
    return {true, ""};
  });

  run("modules that are refused leave the MLP as it was", []() -> Result {
    mc::MLP<I> ANN;
    if (!ANN.read_data("torch_tanh.pt")) return {false, "torch_tanh.pt not read"};
    std::vector<double> const x = points(2)[0];
    auto const ref = derivatives(ANN, x, false), der = derivatives(ANN, x, true);
    // other activation functions, a forward method that does more than its layers, no attribute
    // 'net', a layer of another class, a file that does not exist
    for (std::string const file : {"torch_leakyrelu.pt", "torch_tanhshrink.pt", "torch_softplus.pt", "torch_scaled.pt",
                                   "torch_nonet.pt", "torch_mylinear.pt", "torch_missing.pt"})
    {
      if (ANN.read_data(file)) return {false, file + " read"};
      if (ANN.nin() != 2 || ANN.nout() != 2) return {false, file + ": sizes changed"};
      if (derivatives(ANN, x, false) != ref) return {false, file + ": MC++ evaluation changed"};
      if (derivatives(ANN, x, true) != der) return {false, file + ": Torch evaluation changed"};
    }
    // and a module that is read replaces the previous one
    if (!ANN.read_data("torch_out_activ.pt") || ANN.nout() != 3) return {false, "torch_out_activ.pt not read"};
    auto const ref2 = derivatives(ANN, x, false), der2 = derivatives(ANN, x, true);
    return {near(der2[0], ref2[0], 1e-5) && near(der2[1], ref2[1], 1e-5), "after reading another module"};
  });

  run("read_data prints nothing unless asked", []() -> Result {
    std::ostringstream out, err;
    auto* const pout = std::cout.rdbuf(out.rdbuf());
    auto* const perr = std::cerr.rdbuf(err.rdbuf());
    mc::MLP<I> ANN;
    bool const ok1 = ANN.read_data("torch_tanh.pt"), ok2 = ANN.read_data("torch_softplus.pt");
    size_t const nquiet = out.str().size() + err.str().size();
    bool const ok3 = ANN.read_data("torch_tanh.pt", true);
    std::cout.rdbuf(pout);
    std::cerr.rdbuf(perr);
    return {ok1 && !ok2 && ok3 && nquiet == 0 && !out.str().empty(), std::to_string(nquiet) + " characters printed"};
  });

  run("copies and assigned MLPs evaluate through Torch too", []() -> Result {
    mc::MLP<I> ANN, ANN3;
    if (!ANN.read_data("torch_out_activ.pt") || !ANN3.read_data("torch_tanh.pt")) return {false, "not read"};
    mc::MLP<I> ANN2(ANN);
    ANN3 = ANN;
    for (auto const& x : points(2))
      for (mc::MLP<I>* pANN : {&ANN2, &ANN3})
      {
        if (derivatives(*pANN, x, true) != derivatives(ANN, x, true)) return {false, "Torch evaluation of the copy"};
        if (derivatives(*pANN, x, false) != derivatives(ANN, x, false)) return {false, "MC++ evaluation of the copy"};
      }
    // reading another module in the original leaves the copies with theirs
    std::vector<double> const x = points(2)[0];
    auto const der = derivatives(ANN2, x, true);
    if (!ANN.read_data("torch_tanh.pt")) return {false, "not read"};
    return {derivatives(ANN2, x, true) == der && derivatives(ANN3, x, true) == der, "copies after the original read another module"};
  });

  run("evaluation through Torch from several threads", []() -> Result {
    // the Torch code paths keep no state in the MLP: one object serves all the threads
    for (std::string const file : {"torch_out_activ.pt", "torch_nobatch.pt"})
    {
      mc::MLP<I> ANN;
      if (!ANN.read_data(file)) return {false, file + " not read"};
      size_t const nin = ANN.nin(), nout = ANN.nout(), npts = 3;
      auto const pts = points(nin);
      std::vector<std::vector<std::vector<double>>> ref(npts);
      for (size_t k = 0; k < npts; ++k) ref[k] = derivatives(ANN, pts[k], true);
      ANN.options.EVALTORCH = true;
      std::vector<int> nbad(4, 0);
      std::vector<std::string> error(4);
      std::vector<std::thread> threads;
      for (size_t ith = 0; ith < 4; ++ith)
        threads.emplace_back([&, ith]() {
          try
          {
            std::vector<double> y(nout), J(nout * nin), d(nin), w(nout), t(nout), a(nin);
            for (size_t i = 0; i < nin; ++i) d[i] = 0.5 - 0.3 * i;
            for (size_t k = 0; k < nout; ++k) w[k] = 1. + 0.7 * k;
            for (size_t it = 0; it < 200; ++it)
            {
              size_t const k = (it + ith) % npts;
              ANN.eval(pts[k].data(), y.data());
              ANN.grad(pts[k].data(), J.data());
              ANN.tang(pts[k].data(), d.data(), t.data());
              ANN.adj(pts[k].data(), w.data(), a.data());
              if (!std::equal(y.begin(), y.end(), ref[k][0].begin()) || J != ref[k][1] || t != ref[k][2] || a != ref[k][3]) ++nbad[ith];
            }
          }
          catch (std::exception const& e)
          {
            error[ith] = e.what();
          }
        });
      for (auto& th : threads) th.join();
      ANN.options.EVALTORCH = false;
      for (size_t ith = 0; ith < 4; ++ith)
      {
        if (!error[ith].empty()) return {false, file + ": exception in a thread: " + error[ith].substr(0, 100)};
        if (nbad[ith]) return {false, file + ": " + std::to_string(nbad[ith]) + " evaluations differ in a thread"};
      }
    }
    return {true, ""};
  });

  run("FFMLP in a DAG: derivative operations evaluated through Torch", []() -> Result {
    mc::MLP<I> ANN, ANNT;
    if (!ANN.read_data("torch_out_activ.pt") || !ANNT.read_data("torch_out_activ.pt")) return {false, "not read"};
    ANNT.options.EVALTORCH = ANNT.options.TANGENT = ANNT.options.ADJOINT = true;
    mc::FFGraph DAG;
    std::vector<mc::FFVar> Q = DAG.add_vars(3), W = DAG.add_vars(2);
    std::vector<mc::FFVar> const X = {Q[0] * Q[1], Q[1] - 2. * Q[2]};
    mc::FFMLP<I> Op, OpT;
    std::vector<mc::FFVar> const Y = Op(X, &ANN), YT = OpT(X, &ANNT);
    std::vector<mc::FFVar> const F = {Y[0] * Y[1] + Q[2], exp(Y[2])}, FT = {YT[0] * YT[1] + Q[2], exp(YT[2])};
    // Jacobian operation without the options; tangent and adjoint operations with them
    std::vector<std::vector<mc::FFVar>> const dF  = {DAG.FAD(F, Q), DAG.BAD(F, Q), DAG.DFAD(F, Q, Q), DAG.DBAD(F, W, Q)},
                                              dFT = {DAG.FAD(FT, Q), DAG.BAD(FT, Q), DAG.DFAD(FT, Q, Q), DAG.DBAD(FT, W, Q)};
    std::vector<mc::FFVar> QW = Q;
    QW.insert(QW.end(), W.begin(), W.end());
    std::vector<double> const qw = {0.3, -0.7, 1.1, 0.5, -2.};
    for (size_t k = 0; k < dF.size(); ++k)
    {
      std::vector<double> d(dF[k].size()), dT(dFT[k].size()), f(2), fT(2);
      DAG.eval(dF[k], d, QW, qw);
      DAG.eval(dFT[k], dT, QW, qw);
      if (!near(dT, d, 1e-5)) return {false, "derivatives " + std::to_string(k)};
      DAG.eval(F, f, QW, qw);
      DAG.eval(FT, fT, QW, qw);
      if (!near(fT, f, 1e-5)) return {false, "values"};
    }
    return {true, ""};
  });

  std::printf("\n=== Results: %d/%d passed ===\n", test::passed, test::total);
  return test::failed ? 1 : 0;
#endif
}
